from pathlib import Path

path = Path('/home/ubuntu/quji-event-service-prototype/client/src/pages/Home.tsx')
s = path.read_text()

def once(old: str, new: str, label: str):
    global s
    if old not in s:
        raise SystemExit(f'Missing target: {label}')
    s = s.replace(old, new, 1)

old_action = """function ActionButton({ label, className, title, description, icon }: { label: string; className: string; title?: string; description?: string; icon?: ReactNode }) { const [state, setState] = useState<'confirm' | 'done' | null>(null); const heading = title || label; return <><button onClick={() => setState('confirm')} className={className}>{icon}{label}</button>{state && <div className="fixed inset-0 z-[60] flex items-center justify-center p-4"><button onClick={() => setState(null)} className="absolute inset-0 bg-black/30" /><section className="relative w-full max-w-[440px] bg-white rounded-xl shadow-2xl p-6"><div className="w-11 h-11 rounded-xl bg-blue-50 text-[#255ec8] flex items-center justify-center">{state === 'done' ? <CheckCircle2 className="w-5 h-5" /> : (icon || <ClipboardCheck className="w-5 h-5" />)}</div><h2 className="mt-4 text-[20px] font-semibold">{state === 'done' ? `${heading}已完成` : heading}</h2><p className="mt-2 text-[14px] leading-6 text-slate-600">{state === 'done' ? '本次操作已登记，并将同步写入当前活动的操作记录。' : (description || '请确认本次操作，系统将记录处理人、处理时间和关联活动。')}</p><div className="mt-6 flex justify-end gap-2"><button onClick={() => setState(null)} className="h-10 px-4 rounded-lg border border-slate-300 text-[14px] font-semibold">{state === 'done' ? '关闭' : '取消'}</button>{state === 'confirm' && <button onClick={() => setState('done')} className="h-10 px-4 rounded-lg bg-[#255ec8] text-white text-[14px] font-semibold">确认</button>}</div></section></div>}</>; }"""
new_action = """function ActionButton({ label, className, title, description, icon }: { label: string; className: string; title?: string; description?: string; icon?: ReactNode }) {
  const [state, setState] = useState<'view' | 'edit' | 'done' | null>(null);
  const [note, setNote] = useState('');
  const heading = title || label;
  const exporting = label.includes('导出');
  const reviewing = /查看|记录|资料/.test(label);
  const secondStep = exporting ? '选择范围' : reviewing ? '补充或更新' : '确认处理';
  const finalStep = exporting ? '生成文件' : '提交并写入记录';
  const close = () => { setState(null); setNote(''); };
  const meta = exporting ? '当前活动 · 数据归集范围已加载' : '当前活动 · 关联资料与操作记录已加载';
  return <><button onClick={() => setState('view')} className={className}>{icon}{label}</button>{state && <div className="fixed inset-0 z-[60] flex justify-end"><button aria-label="关闭任务面板" onClick={close} className="absolute inset-0 bg-slate-950/20" /><aside className="task-drawer relative h-full w-full max-w-[560px] bg-white flex flex-col"><header className="px-6 py-5 border-b border-slate-200 flex items-start justify-between"><div><div className="text-[13px] font-semibold text-slate-500">任务处理</div><h2 className="mt-1 text-[22px] leading-7 font-semibold text-slate-900">{heading}</h2><p className="mt-1 text-[14px] text-slate-600">{meta}</p></div><button onClick={close} aria-label="关闭" className="w-9 h-9 -mr-1 rounded-md text-slate-500 hover:bg-slate-100 flex items-center justify-center"><X className="w-5 h-5" /></button></header><div className="px-6 py-4 border-b border-slate-200 grid grid-cols-3 gap-2">{[['查看当前资料', 'view'], [secondStep, 'edit'], [finalStep, 'done']].map(([step, id], index) => <div key={id as string} data-active={state === id} className="task-step rounded-md border border-transparent px-3 py-2 min-w-0"><div className="text-[11px] font-semibold text-slate-500">0{index + 1}</div><div className="mt-1 text-[13px] font-semibold whitespace-nowrap">{step}</div></div>)}</div><div className="flex-1 overflow-y-auto p-6">{state === 'view' && <div className="space-y-5"><section className="border border-slate-200 rounded-lg divide-y divide-slate-200"><TaskField label="当前状态" value={exporting ? '数据已汇总，可按范围生成文件' : '资料已归集，可查看版本与处理记录'} /><TaskField label="关联内容" value={description || '当前活动关联材料、处理意见与操作时间'} /><TaskField label="最近更新" value="今天 10:36 · 主办方运营组" /></section><section><h3 className="text-[15px] font-semibold">操作记录</h3><div className="mt-3 space-y-3"><TimelineRow text="已加载当前版本与关联记录" time="刚刚" /><TimelineRow text="主办方更新活动材料" time="今天 10:36" /><TimelineRow text="协同人员完成资料核验" time="昨天 16:30" /></div></section></div>}{state === 'edit' && <div className="space-y-5"><section className="border border-slate-200 rounded-lg p-4"><h3 className="text-[15px] font-semibold">{exporting ? '导出范围' : '处理说明'}</h3><p className="mt-1 text-[14px] leading-6 text-slate-600">{exporting ? '默认包含当前活动的已归集数据与操作记录。' : '填写本次补充、修订或处理说明，提交后会写入活动记录。'}</p><textarea value={note} onChange={e => setNote(e.target.value)} placeholder={exporting ? '例如：用于本周运营复盘' : '例如：已补充主体资质文件第 2 版'} className="mt-4 w-full min-h-28 resize-none rounded-md border border-slate-300 px-3 py-2 text-[14px] leading-6 outline-none focus:border-[#245fc4]" /></section><label className="flex items-start gap-3 rounded-lg bg-slate-50 p-4 text-[14px] leading-6 text-slate-700"><input type="checkbox" defaultChecked className="mt-1 w-4 h-4 accent-[#245fc4]" />同步写入当前活动操作记录，并保留本次处理时间与操作人。</label></div>}{state === 'done' && <div className="py-12 text-center"><div className="mx-auto w-11 h-11 rounded-full bg-emerald-50 text-emerald-700 flex items-center justify-center"><CheckCircle2 className="w-6 h-6" /></div><h3 className="mt-4 text-[20px] font-semibold">{exporting ? '活动文件已生成' : '任务已提交并登记'}</h3><p className="mt-2 max-w-sm mx-auto text-[14px] leading-6 text-slate-600">{exporting ? '文件已按当前活动数据范围生成，可在活动档案中继续查看。' : '本次处理已写入当前活动的操作记录，可继续处理下一项待办。'}</p></div>}</div><footer className="px-6 py-4 border-t border-slate-200 flex items-center justify-between gap-3"><button onClick={close} className="h-10 px-4 rounded-md border border-slate-300 text-[14px] font-semibold text-slate-700 hover:bg-slate-50">{state === 'done' ? '返回列表' : '暂存并返回'}</button>{state !== 'done' && <button onClick={() => setState(state === 'view' ? 'edit' : 'done')} className="h-10 px-4 rounded-md bg-[#245fc4] hover:bg-[#1c4c9e] text-white text-[14px] font-semibold flex items-center gap-2">{state === 'view' ? `下一步：${secondStep}` : finalStep}<ArrowRight className="w-4 h-4" /></button>}</footer></aside></div>}</>;
}
function TaskField({ label, value }: { label: string; value: string }) { return <div className="px-4 py-3"><div className="text-[12px] font-semibold text-slate-500">{label}</div><div className="mt-1 text-[14px] leading-6 text-slate-800 semantic-copy">{value}</div></div>; }
function TimelineRow({ text, time }: { text: string; time: string }) { return <div className="flex gap-3"><div className="mt-2 w-2 h-2 rounded-full bg-[#245fc4] shrink-0" /><div className="min-w-0"><div className="text-[14px] text-slate-800">{text}</div><div className="mt-1 text-[12px] text-slate-500">{time}</div></div></div>; }"""
once(old_action, new_action, 'generic confirmation action')

old_sidebar = """<div className="p-3 border-t border-slate-200"><button onClick={() => setSidebarCollapsed(!sidebarCollapsed)} title={sidebarCollapsed ? '展开侧边栏' : '收起侧边栏'} className={`mb-2 w-full h-9 rounded-lg border border-slate-200 flex items-center text-[13px] font-semibold text-slate-600 hover:bg-slate-50 ${sidebarCollapsed ? 'justify-center px-2' : 'px-3 gap-2'}`}><PanelLeftClose className={`w-4 h-4 transition-transform ${sidebarCollapsed ? 'rotate-180' : ''}`} />{!sidebarCollapsed && <span>收起菜单</span>}</button>"""
new_sidebar = """<div className={`p-3 border-t border-slate-200 ${sidebarCollapsed ? 'flex justify-center' : ''}`}><button onClick={() => setSidebarCollapsed(!sidebarCollapsed)} title={sidebarCollapsed ? '展开侧边栏' : '收起侧边栏'} aria-label={sidebarCollapsed ? '展开侧边栏' : '收起侧边栏'} className="mb-2 w-8 h-8 rounded-md border border-slate-200 flex items-center justify-center text-slate-500 hover:text-slate-900 hover:bg-slate-50"><PanelLeftClose className={`w-4 h-4 transition-transform ${sidebarCollapsed ? 'rotate-180' : ''}`} /></button>"""
once(old_sidebar, new_sidebar, 'sidebar collapse control')

old_info = """function InfoBlock({ label, value }: { label: string; value: string }) { return <div className="p-4 rounded-lg bg-slate-50"><div className="text-[13px] text-slate-500">{label}</div><div className="mt-2 text-[15px] leading-6 font-semibold">{value}</div></div>; }"""
new_info = """function InfoBlock({ label, value }: { label: string; value: string }) { return <div className="p-4 rounded-md bg-slate-50"><div className="text-[13px] text-slate-500 whitespace-nowrap">{label}</div><div className="data-token mt-2 text-[15px] leading-6 font-semibold">{value}</div></div>; }"""
once(old_info, new_info, 'InfoBlock tokens')

